import {yupResolver} from '@hookform/resolvers/yup';
import React from 'react';
import {
  Controller,
  FormProvider,
  useForm,
  useFormContext,
} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {
  KeyboardAvoidingView,
  Modal,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import * as yup from 'yup';
import styles from './styles';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import TextField from '../../../../../components/TextField';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type ModalNotificationRecipientProp = {
  onClose: () => void;
  isVisible: boolean;
  documentId: string;
  recipientId: string;
};

const ModalNotificationRecipient = ({
  documentId,
  recipientId,
  onClose,
  isVisible,
}: ModalNotificationRecipientProp) => {
  const {t} = useTranslation();
  const schema = yup.object().shape({
    text: yup.string().required(t('SU.fieldRequired')),
  });
  const insets = useSafeAreaInsets();
  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
  });

  const DocumentServices = useDocumentServices();

  const onSubmit = async () => {
    try {
      const res = await DocumentServices.postNotificationMessage(
        recipientId,
        documentId,
        methods.getValues('text'),
      );
      Toast.show({
        type: 'success',
        text1: t('DC.notifyRecipientSuccess'),
      });
    } catch (error) {
    } finally {
      onClose();
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <View style={styles.ctnContainer}>
          <View style={styles.ctnTop} onTouchEnd={onClose} />
          <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <View style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IcBlackLeftArrow width={14} height={16} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>
                {t('CM.TxtTabNotifications')}
              </TextCM>
              <View />
            </View>
            <View style={styles.viewBody}>
              <FormProvider {...methods}>
                <YupTextArea
                  controlName="text"
                  label={t('DC.typeNotification')}
                  maxLength={100}
                />
                <ButtonCM
                  disabled={!methods.formState.isValid}
                  label={t('CM.TxtTabNotifications')}
                  onPress={onSubmit}
                />
              </FormProvider>
            </View>
          </View>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
};

type Props = {
  controlName: string;
  label: string;
  maxLength?: number;
  onPressIconRight?: () => void;
  viewIconRight?: React.ReactNode;
};

const YupTextArea = ({
  controlName,
  label,
  maxLength,
  onPressIconRight,
  viewIconRight,
}: Props) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  return (
    <View>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          return (
            <TextField
              label={label}
              placeholder={label}
              isRequired={true}
              value={value}
              onBlur={onBlur}
              onChangeText={onChange}
              onIconPress={onPressIconRight}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={viewIconRight}
              multiline={true}
            />
          );
        }}
      />
    </View>
  );
};

export default ModalNotificationRecipient;
