import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, Modal, TouchableOpacity, View} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';
import {IReasonTemplate} from '../../../../../model/interface/envelope.interface';
import {
  IcBlackLeftArrow,
  IconBlackUp,
  IconRadio,
  IconRedDelete,
} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ModalConfirm from '../../../../../components/ModalConfirm';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type ModalPicReasonTemplate = {
  onClose: () => void;
  isVisible: boolean;
  onPicTemplate: (value: any) => void;
};

const ModalPicReasonTemplate = ({
  onClose,
  isVisible,
  onPicTemplate,
}: ModalPicReasonTemplate) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();

  const [data, setData] = useState<IReasonTemplate[]>([]);
  const [showModalDelete, setShowModalDelete] = useState(false);

  const [currentItem, setCurrentItem] = useState<IReasonTemplate>();

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    if (isVisible) getData();
  }, [isVisible]);

  const getData = async () => {
    const data = await DocumentServices.getListReasonTemplate();
    setData(data.sort((a: any, b: any) => a.priority - b.priority));
  };

  const onPressItem = (item: IReasonTemplate) => {
    onPicTemplate(item);
    onClose();
  };

  const toggleModalDelete = () => {
    setShowModalDelete(!showModalDelete);
  };

  const onPressUpPriority = async (item: IReasonTemplate) => {
    const indexCurrent = data.findIndex(i => i.id === item.id);
    const indexPrev = indexCurrent - 1;
    if (indexPrev >= 0) {
      const temp = data[indexCurrent];
      data[indexCurrent] = data[indexPrev];
      data[indexPrev] = temp;
      setData([...data]);
      DocumentServices.saveListReasonTemplate([
        ...data.map((i, index) => ({
          ...i,
          priority: index,
        })),
      ]);
    }
  };

  const onPressDeletePriority = (item: IReasonTemplate) => {
    DocumentServices.deleteReasonTemplate(item.id).then(() => {
      getData();
    });
  };

  const onConfirmDelete = () => {
    toggleModalDelete();
    if (currentItem) {
      onPressDeletePriority(currentItem);
    }
  };

  const renderItem = ({
    item,
    index,
  }: {
    item: IReasonTemplate;
    index: number;
  }) => {
    return (
      <TouchableOpacity
        style={styles.viewItem}
        onPress={() => {
          onPressItem(item);
        }}>
        <IconRadio width={24} height={24} />
        <TextCM style={styles.txtItem} numberOfLines={1}>
          {item.content}
        </TextCM>
        <View style={styles.viewAction}>
          {index > 0 && (
            <TouchableOpacity
              onPress={() => {
                onPressUpPriority(item);
              }}>
              <IconBlackUp width={16} height={18} />
            </TouchableOpacity>
          )}
          <TouchableOpacity
            onPress={() => {
              setCurrentItem(item);
              toggleModalDelete();
            }}>
            <IconRedDelete width={16} height={18} />
          </TouchableOpacity>
        </View>
      </TouchableOpacity>
    );
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('DC.CancelDocument.TxtReasonTemplate')}
            </TextCM>
            <View />
          </View>
          <View style={styles.viewBody}>
            <TextCM style={styles.txtTitlePic}>
              {t('DC.CancelDocument.TxtPicReasonTemplate')}
            </TextCM>
            <FlatList
              data={data}
              keyExtractor={item => item.id.toString()}
              renderItem={renderItem}
              contentContainerStyle={styles.ctnFlatList}
              showsVerticalScrollIndicator={false}
            />
          </View>
        </View>
      </View>
      <ModalConfirm
        isVisible={showModalDelete}
        onClose={toggleModalDelete}
        title={t('DC.CancelDocument.TxtConfirmDeleteTemplate')}
        labelConfirm={t('DC.BtnRemove')}
        onConfirm={onConfirmDelete}
      />
    </Modal>
  );
};

export default ModalPicReasonTemplate;
