import React, {FC, Fragment} from 'react';
import {Linking, ScrollView, TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {isEmpty} from 'lodash';
import {IFieldsByHeader} from '../../../../../model/interface/envelope.interface';
import {useAppSelector} from '../../../../../hook/useRedux';
import TextCM from '../../../../../components/Text';
import {DateUtils} from '../../../../../utils';
import {SignType} from '../../../../../model/interface/notification.interface';
import {Color} from '../../../../../constants';

type Props = {
  data: IFieldsByHeader[];
  dataEkyc: any[];
};
const ListGeneralInfoDocument: FC<Props> = ({data, dataEkyc}) => {
  const {t} = useTranslation();
  const account = useAppSelector(state => state.account.dataAccount);

  const renderItem = (item: IFieldsByHeader) => {
    return (
      // <View style={styles.ctnItem} key={index}>
      //   <TextCM style={styles.txtKey}>{item.name}</TextCM>
      //   <TextCM style={[styles.txtKey, styles.txtValue]}>
      //     {item.type === 'Date'
      //       ? DateUtils.convertDateToDDMMYYYY(item.value) || '---'
      //       : item.value || '---'}
      //   </TextCM>
      // </View>
      <View key={item.id}>
        {!isEmpty(item.value) && (
          <View style={styles.ctnItem}>
            <TextCM style={styles.txtKey}>{item.name}</TextCM>
            <TextCM style={[styles.txtKey, styles.txtValue]}>
              {item.type === 'Date'
                ? DateUtils.convertDateToDDMMYYYY(item.value) || '---'
                : item.value || '---'}
            </TextCM>
          </View>
        )}
      </View>
    );
  };

  const checkEkyc = dataEkyc?.some((item: any) => {
    if (
      item?.contact?.name === account.lastName &&
      item?.contact?.email === account.email
    ) {
      return true;
    }
    return false;
  });

  const handleViewEkyc = (id: string) => {
    if (!id) return;
    Linking.openURL(`https://econtract.fpt.com/app/kyc/details/${id}`);
  };

  return (
    <View style={styles.ctnFlatlist}>
      <View style={styles.ctnLine} />
      <TextCM style={styles.txtTitle}>{t('DC.TxtGeneralInformation')}</TextCM>
      <ScrollView>
        {data.length > 0 && data.map(renderItem)}
        {dataEkyc?.length === 1 && checkEkyc ? null : dataEkyc?.length > 0 ? (
          <View style={styles.ctnMainEkyc}>
            <TextCM style={styles.txtKey}>{t('DC.TxtDetailEkyc')}</TextCM>
            <View style={styles.ctnItemEkyc}>
              {dataEkyc.map((item: any, index) => {
                return (
                  <Fragment key={index}>
                    {item?.signTypes?.includes(SignType.EKYC) &&
                    item?.status === 'accepted' ? (
                      <TouchableOpacity
                        onPress={() => handleViewEkyc(item?.ekycDetail?.id)}
                        style={styles.ctnListUserEkyc}
                        key={index}>
                        <TextCM
                          style={[
                            styles.txtKey,
                            styles.txtValue,
                            {
                              color: Color.Primary,
                            },
                          ]}>
                          {item?.contact?.name}
                        </TextCM>
                        <TextCM
                          style={[
                            styles.txtKey,
                            styles.txtValue,
                            {
                              color: Color.Primary,
                              textDecorationColor: Color.Primary,
                              textDecorationLine: 'underline',
                            },
                          ]}>
                          {item.contact.email}
                        </TextCM>
                      </TouchableOpacity>
                    ) : (
                      <TouchableOpacity
                        onPress={() => handleViewEkyc(item?.ekycDetail?.id)}
                        style={styles.ctnListUserEkyc}
                        key={index}>
                        <TextCM style={[styles.txtKey, styles.txtValue]}>
                          ---
                        </TextCM>
                      </TouchableOpacity>
                    )}
                  </Fragment>
                );
              })}
            </View>
          </View>
        ) : null}
      </ScrollView>
    </View>
  );
};

export default ListGeneralInfoDocument;
