import {FC, useEffect, useState} from 'react';
import {TouchableOpacity, View} from 'react-native';
import styles from '../../styles';
import {useTranslation} from 'react-i18next';
import {textDisplayList} from '../../helper';
import {isEmpty} from 'lodash';
import CheckboxCM from '../../../../components/Checkbox';
import TextCM from '../../../../components/Text';
import ButtonCM from '../../../../components/Button';
import { RightArrowGrey } from '../../../../assets/images';
import BottomSheetCM from '../../../../components/BottomSheet';
import { SizeDP } from '../../../../constants/Size';

type Props = {
  valueTextDisplay: any;
  onChangeTextDisplay: (value: any) => void;
};

const ConfigShowText: FC<Props> = ({valueTextDisplay, onChangeTextDisplay}) => {
  const {t} = useTranslation();
  const [isVisible, setIsVisiable] = useState<boolean>(false);
  const [dataSelect, setDataSelect] = useState<any>();
  const [valueChange, setValueChange] = useState<any>();

  useEffect(() => {
    setValueChange(valueTextDisplay);
    const newDataSelect = textDisplayList.map(item => {
      return {
        ...item,
        select: valueTextDisplay[item.key],
      };
    });
    setDataSelect(newDataSelect);
  }, [valueTextDisplay]);

  const handleChangeSelect = (value: boolean, key: string) => {
    const newData = {
      ...valueChange,
      [key]: value,
    };
    setValueChange(newData);
  };

  const handleSaveData = () => {
    const newDataSelect = dataSelect.map((item: any) => {
      return {
        ...item,
        select: valueChange[item.key],
      };
    });
    setDataSelect(newDataSelect);
    onChangeTextDisplay(valueChange);
    setIsVisiable(false);
  };

  const handleCloseBottomSheet = () => {
    setValueChange(valueTextDisplay);
    setIsVisiable(false);
  };

  const renderListShowText = () => {
    return (
      <>
        <View>
          {!isEmpty(dataSelect) &&
            dataSelect.map((item: any, index: number) => (
              <View key={index} style={styles.renderConfigShowText}>
                <CheckboxCM
                  checked={valueChange[item.key]}
                  onChange={() =>
                    handleChangeSelect(!valueChange[item.key], item.key)
                  }
                />
                <TextCM>{t(`AC.config.${item.key}`)}</TextCM>
              </View>
            ))}
        </View>
        <ButtonCM label={t('CM.TxtSave')} onPress={handleSaveData} />
      </>
    );
  };
  return (
    <>
      <View style={[styles.ctnConfigList, {borderBottomWidth: 0}]}>
        <TextCM style={styles.textConfig}>{t('AC.showText')}</TextCM>
        <TouchableOpacity
          onPress={() => setIsVisiable(true)}
          style={styles.ctnWithArrow}>
          {!isEmpty(dataSelect) && (
            <TextCM style={styles.colorTextSelect}>
              {dataSelect
                .filter((item: any) => item.select)
                .map((item: any) => t(`AC.config.${item.key}`))
                .join(', ')}
            </TextCM>
          )}
          <RightArrowGrey width={SizeDP(20)} height={SizeDP(20)} />
        </TouchableOpacity>
      </View>
      <BottomSheetCM
        title={t('AC.showText')}
        isVisible={isVisible}
        onClose={handleCloseBottomSheet}
        renderContent={renderListShowText()}
      />
    </>
  );
};

export default ConfigShowText;
