import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {ActivityIndicator, Modal, TouchableOpacity, View} from 'react-native';
import styles from './styles';

import {isEmpty} from 'lodash';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {GroupData} from '../../../../../../../components/GroupRadio';
import {IcBlackLeftArrow} from '../../../../../../../assets/images';
import TextCM from '../../../../../../../components/Text';
import GroupListCheck from '../../../../../../../components/GroupListCheck';
import ButtonCM from '../../../../../../../components/Button';

type ModalListMemberProp = {
  onClose: () => void;
  isVisible: boolean;
  data: GroupData[];
  onPress: (item: GroupData[]) => void;
  loading: boolean;
};

const ModalListMember = ({
  onClose,
  isVisible,
  data,
  onPress,
  loading,
}: ModalListMemberProp) => {
  const {t} = useTranslation();
  const [currentSelected, setCurrentSelected] = useState<GroupData[]>([]);
  const insets = useSafeAreaInsets();

  const handleData = React.useMemo(() => {
    return [{label: t('DC.all'), id: 'all'}, ...data];
  }, [data]);
  const hanndleOnpress = (item: GroupData) => {
    if (currentSelected.includes(item)) {
      if (item.id === 'all') {
        setCurrentSelected([]);
      }
      setCurrentSelected(prev => prev.filter(i => i.id !== item.id));
    } else {
      if (item.id === 'all') {
        setCurrentSelected(handleData.slice(1));
      }
      setCurrentSelected(prev => [...prev, item]);
    }
  };

  const handleOnsubmit = () => {
    const dataReturn = currentSelected.filter(i => i.id !== 'all');
    onPress(dataReturn);
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{t('DC.TxtListMember')}</TextCM>
            <View />
          </View>
          {loading ? (
            <View
              style={{flex: 1, alignItems: 'center', justifyContent: 'center'}}>
              <ActivityIndicator size="large" color="#32322f" />
            </View>
          ) : (
            <View style={styles.viewBody}>
              <TextCM style={styles.txtLabel}>{t('DC.TxtChooseMember')}</TextCM>
              <GroupListCheck
                data={handleData}
                onPressData={hanndleOnpress}
                currentValue={currentSelected}
                scrollEnabled={true}
              />
            </View>
          )}
          <View style={styles.GroupButton}>
            <ButtonCM
              type="white"
              label={t('DC.TxtDeleteAll')}
              onPress={() => {
                setCurrentSelected([]);
              }}
              style={{flex: 1}}
            />
            <ButtonCM
              disabled={isEmpty(currentSelected)}
              label={t('CM.BtnConfirm')}
              onPress={handleOnsubmit}
              style={{flex: 1}}
            />
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default ModalListMember;
