import React from 'react';
import {useTranslation} from 'react-i18next';
import {
  KeyboardAvoidingView,
  Modal,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import * as yup from 'yup';
import styles from './styles';

import {yupResolver} from '@hookform/resolvers/yup';
import {FormProvider, useForm} from 'react-hook-form';
import {useAppSelector} from '../../../../../hook/useRedux';
import Toast from 'react-native-toast-message';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import YupTextField from '../../../../account-info/components/YupTextField';
import ButtonCM from '../../../../../components/Button';
import {useGeneralSettingServices} from '../../../../../hook/apiHook/useApi';

type ModalAddCertificateProp = {
  onClose: () => void;
  isVisible: boolean;
  fetching: () => void;
};

const ModalAddCertificate = ({
  onClose,
  isVisible,
  fetching,
}: ModalAddCertificateProp) => {
  const {t} = useTranslation();
  const {id} = useAppSelector(state => state.account.dataAccount);
  const GeneralSettingServices = useGeneralSettingServices();
  const schema = yup.object().shape({
    userName: yup.string().required(t('SU.fieldRequired')),
    note: yup.string(),
  });

  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues: {
      userName: '',
      note: '',
    },
  });

  const insets = useSafeAreaInsets();

  const onSubmit = async () => {
    try {
      const res = await GeneralSettingServices.createDigitalCertificate(
        id ?? 0,
        methods.getValues('userName'),
        methods.getValues('note') ?? '',
      );
      onClose();
      Toast.show({
        text1: t('CM.MessageAddSuccess'),
        type: 'success',
      });
      fetching();
    } catch (error: any) {
      if (error?.data?.detail === 'duplicate certificate')
        methods.setError('userName', {
          message: t('ST.DigitalCertificate.certificateAlreadyExists'),
        });
      if (error?.data?.detail === 'username is not exsist ')
        methods.setError('userName', {
          message: t('ST.DigitalCertificate.errorMessageSupport'),
        });
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <KeyboardAvoidingView
          behavior={'padding'}
          keyboardVerticalOffset={-insets.bottom}>
          <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <View style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IcBlackLeftArrow width={14} height={16} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>
                {t('ST.DigitalCertificate.addDigitalCertificate')}
              </TextCM>
              <View />
            </View>
            <FormProvider {...methods}>
              <View style={styles.viewBody}>
                <YupTextField
                  controlName="userName"
                  label={t('ST.DigitalCertificate.userName')}
                />
                <YupTextField
                  controlName="note"
                  label={t('ST.DigitalCertificate.note')}
                />
              </View>
              <View style={styles.viewBody}>
                <ButtonCM
                  disabled={!methods.formState.isValid}
                  label={t('CM.TxtSave')}
                  onPress={onSubmit}
                />
              </View>
            </FormProvider>
          </View>
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
};

export default ModalAddCertificate;
