import {TouchableOpacity, Image} from 'react-native';
import React, {useEffect, useState} from 'react';
import styles from './styles';
import {useNavigation} from '@react-navigation/native';
import {View as ViewCM} from 'react-native';
import {
  IconBlueUser,
  IconImageDefault,
  IconOrangePen,
} from '../../../../assets/images';
import {SizeDP} from '../../../../constants/Size';
import {
  IImageDigitalSignature,
  IImageSignature,
} from '../../../../services/interface';
import {NavigationName, String} from '../../../../constants';
import TextCM from '../../../../components/Text';
import {useSettingStore} from '../../../settings/store/settingStore';
import { useTranslation } from 'react-i18next';
import { useAccountServices } from '../../../../hook/apiHook/useApi';

const ImageDefault = () => {
  return (
    <ViewCM style={styles.imageDefault}>
      <IconImageDefault width={SizeDP(40)} height={SizeDP(40)} />
    </ViewCM>
  );
};

const SignatureInfo = () => {
  const navigation = useNavigation<any>();
  const [dataImage, setDataImage] = useState<IImageSignature>();
  const [dataDigital, setDataDigital] = useState<IImageDigitalSignature>();
  const {isReloadingSign} = useSettingStore();
  const accountServices = useAccountServices();
  const {t} = useTranslation()
  useEffect(() => {
    getListData();
  }, [isReloadingSign]);

  const getListData = async () => {
    try {
      const params = {
        name: '',
      };
      const res = await accountServices.listImageSignature(params);
      const resDigital = await accountServices.listImageDigitalSignature(
        params,
      );
      const lsStar = res.find(i => i.star);
      const lsStarDigital = resDigital.find(i => i.star);
      setDataImage(lsStar);
      setDataDigital(lsStarDigital);
    } catch (error) {}
  };

  const onPressEdit = () => {
    navigation.navigate(NavigationName.AccountNavigator);
  };

  return (
    <ViewCM style={styles.container}>
      <ViewCM style={styles.header}>
        <IconBlueUser width={SizeDP(18)} height={SizeDP(18)} />
        <TextCM style={styles.txtHeader}>{t('AI.TxtSignatureInfo')}</TextCM>
        <TouchableOpacity onPress={onPressEdit}>
          <IconOrangePen width={SizeDP(18)} height={SizeDP(18)} />
        </TouchableOpacity>
      </ViewCM>
      <ViewCM style={styles.body}>
        <ViewCM style={styles.viewItem}>
          {dataImage ? (
            <Image
              source={{
                uri: String.PREFIX_IMG_BASE64 + dataImage.signature,
              }}
              style={styles.image}
            />
          ) : (
            <ImageDefault />
          )}
          <TextCM style={styles.txtItem}>{t('AI.TxtSignImage')}</TextCM>
        </ViewCM>
        <ViewCM style={styles.viewItem}>
          {dataDigital?.digitalSignature?.fieldLogoDesign?.value ? (
            <Image
              source={{
                uri:
                  String.PREFIX_IMG_BASE64 +
                  dataDigital?.digitalSignature?.fieldLogoDesign?.value,
              }}
              style={styles.image}
            />
          ) : (
            <ImageDefault />
          )}
          <TextCM style={styles.txtItem}>{t('AC.digitalImageSign')}</TextCM>
        </ViewCM>
      </ViewCM>
    </ViewCM>
  );
};

export default SignatureInfo;
